/**
 * Unit tests for XmlSerializerProvider._rootNameFromConfig()
 */
public class XmlSerializerProvider__rootNameFromConfig_TriageGen1Test {

    private TestableXmlSerializerProvider provider;

    @Mock
    private SerializationConfig config;

    @Mock
    private PropertyName propertyName;

    /**
     * Subclass to expose the protected method for testing
     */
    private static class TestableXmlSerializerProvider extends XmlSerializerProvider {
        public TestableXmlSerializerProvider(SerializationConfig config, SerializerFactory f) {
            super(null, config, f);
        }

        @Override
        public QName _rootNameFromConfig() {
            return super._rootNameFromConfig();
        }
    }

    // Mocking the internal class structure of PropertyName if it's an interface/class used by config
    // Assuming PropertyName is a class/interface available in the context
    public interface PropertyName {
        String getNamespace();
        String getSimpleName();
    }

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Note: Since the constructor requires a SerializerFactory, we pass null or a mock
        provider = new TestableXmlSerializerProvider(config, null);
    }

    @Test
    public void test_rootNameFromConfig_returnsNullWhenNameIsNull() {
        when(config.getFullRootName()).thenReturn(null);

        QName result = provider._rootNameFromConfig();

        assertNull(result);
    }

    @Test
    public void test_rootNameFromConfig_returnsOnlySimpleNameWhenNamespaceIsNull() {
        when(config.getFullRootName()).thenReturn(propertyName);
        when(propertyName.getNamespace()).thenReturn(null);
        when(propertyName.getSimpleName()).thenReturn("root");

        QName result = provider._rootNameFromConfig();

        assertEquals(new QName("root"), result);
    }

    @Test
    public void test_rootNameFromConfig_returnsOnlySimpleNameWhenNamespaceIsEmpty() {
        when(config.getFullRootName()).thenReturn(propertyName);
        when(propertyName.getNamespace()).thenReturn("");
        when(propertyName.getSimpleName()).thenReturn("root");

        QName result = provider._rootNameFromConfig();

        assertEquals(new QName("root"), result);
    }

    @Test
    public void test_rootNameFromConfig_returnsFullQNameWhenNamespaceIsPresent() {
        String ns = "http://example.com";
        String localPart = "root";
        when(config.getFullRootName()).thenReturn(propertyName);
        when(propertyName.getNamespace()).thenReturn(ns);
        when(propertyName.getSimpleName()).thenReturn(localPart);

        QName result = provider._rootNameFromConfig();

        assertEquals(new QName(ns, localPart), result);
    }
}
